describe('HTTP Status Codes Page', () => {
  it('should display the 200 status code page correctly', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a[href="#/status_codes/200"]').click();
    cy.url().should('include', '/status_codes/200');
    cy.contains('This page returned a 200 status code').should('be.visible');
  });

  it('should not change URL when clicking the 404 status code link', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a[href="#/status_codes/404"]').click();
    cy.url().should('include', '/status_codes');
    cy.get('a[href="#/status_codes/404"]').click();
    cy.url().should('include', '/status_codes');
  });
});
